import { Share } from "react-native";
import { formatCurrency } from "@/lib/format";
import type { Tab } from "@/components/insights/InsightsTabBar";

// Generated by Claude Opus (4.6).
const SHARE_OPENERS = [
  "Look what my wallet's been up to this month!",
  "My finances are an open book this month!",
  "Peek into my spending life this month!",
  "Money, money, money — here's mine this month!",
  "Full financial transparency incoming!",
];

/**
 * Converts category totals into integer percentages that sum to exactly 100.
 *
 * Naively rounding each percentage independently causes the sum to drift (e.g.,
 * 66.6% + 26.7% + 6.7% rounds to 67+27+7 = 101%). This uses the largest
 * remainder method to fix that: floor every value first, then hand out the
 * missing points one-by-one to whichever categories have the biggest
 * fractional remainders — i.e., the ones that lost the most from flooring.
 *
 * Generated by Claude Opus (4.6).
 */
function allocatePercentages(categories: { total: number }[], grandTotal: number): number[] {
  if (grandTotal === 0) {
    return categories.map(() => 0);
  }

  const exact = categories.map((cat) => (cat.total / grandTotal) * 100);
  const floored = exact.map(Math.floor);
  const remainder = 100 - floored.reduce((a, b) => a + b, 0);

  exact
    .map((v, i) => ({ i, frac: v - Math.floor(v) }))
    .sort((a, b) => b.frac - a.frac)
    .slice(0, remainder)
    .forEach(({ i }) => floored[i]++);

  return floored;
}

function buildShareMessage(type: Tab, total: number, categories: { name: string; total: number }[]): string {
  const opener = SHARE_OPENERS[Math.floor(Math.random() * SHARE_OPENERS.length)];
  const verb = type === "income" ? "earned" : "spent";
  const emoji = type === "income" ? "💰" : "💸";

  const lines = [
    `${opener} 🎉`,
    "",
    `${emoji} Last 30 days: I ${verb} ${formatCurrency(total)}`,
    "",
  ];

  if (categories.length > 0) {
    lines.push(type === "spendings" ? "Here's where my money went:" : "Here's where my money came from:");

    const percentages = allocatePercentages(categories, total);
    for (let i = 0; i < categories.length; i++) {
      lines.push(`  • ${categories[i].name} — ${formatCurrency(categories[i].total)} (${percentages[i]}%)`);
    }

    lines.push("");
  }

  lines.push("Tracked with PocketFlow 📱");

  return lines.join("\n");
}

export function useInsightsShare(activeTab: Tab, total: number, categories: { name: string; total: number }[]) {
  return async () => {
    const message = buildShareMessage(activeTab, total, categories);
    await Share.share({ message });
  };
}
